## Section1(not reported)
## Problem1(3.10.19)
## Author()
## Institution()
## Language(en-US)

DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PCCmacros.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

($x, $y) = random_subset(2, 2..9);
$C = lcm($x,$y);
($x, $y) = (random(0,1))
  ? (-$x, $y)
  : ($x, -$y);
$C = lcm($x,$y);
$A = $C/$x;
$B = $C/$y;
Context()->variables->add(y => 'Real');
Context()->noreduce('(-x)-y', '(-x)+y');
$left = Formula("$A x + $B y")->reduce;
$right = Formula("$C");
$xi = Point($x,0);
$yi = Point(0,$y);
Context("Fraction");
$m = Fraction(-$y/$x);
Context()->variables->add(solvar => 'Real');
Context()->flags->set(reduceConstants => 0);
$sol = Formula("solvar - ($A x)")->reduce;
$sol = $sol->substitute(solvar => Formula("$C"));
$sol2 = Formula("$m x + $C/$B");

######
# Body
######

BEGIN_PGML
[`[$left]=[$right]`]

[@KeyboardInstructions('Enter the [`x`]-intercept here.')@]**

[_]{$xi}{5}

[@KeyboardInstructions('Enter the [`y`]-intercept here.')@]**

[_]{$yi}{5}

[@KeyboardInstructions('Enter the slope here.')@]**

[_]{$m}{5}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
Find the [`x`]-intercept by setting [`y=0\text{.}`] That makes [`[$A]x=[$C]\text{,}`] so [`x=[$x]\text{.}`] And the [`x`]-intercept is at [`[$xi]\text{.}`]

Find the [`y`]-intercept by setting [`x=0\text{.}`] That makes [`[$B]y=[$C]\text{,}`] so [`y=[$y]\text{.}`] And the [`y`]-intercept is at [`[$yi]\text{.}`]

Find the slope by isolating [`y\text{:}`]

[```
\begin{aligned}
[$left] \amp= [$right]\\
[$B] y \amp= [$sol]\\
y \amp= \frac{[$sol]}{[$B]}\\
y \amp= [$sol2]
\end{aligned}
```]

So the slope is [`[$m]\text{.}`]

END_PGML_SOLUTION

#############
# End Problem
#############

ENDDOCUMENT();
